export function isBalanced(source) {
  if (typeof source !== 'string') throw new TypeError('isBalanced expects a string');
  const open = '([{';
  const close = ')]}';
  const stack = [];
  let inString = null;
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    if (inString !== null) {
      if (ch === '\\') {
        i += 2;
        continue;
      }
      if (ch === inString) inString = null;
      i += 1;
      continue;
    }
    if (ch === '"' || ch === "'") {
      inString = ch;
      i += 1;
      continue;
    }
    if (open.includes(ch)) stack.push(ch);
    else if (close.includes(ch)) {
      if (stack.pop() !== open[close.indexOf(ch)]) return false;
    }
    i += 1;
  }
  return inString === null && stack.length === 0;
}
